from pathlib import Path
from typing import Callable

import pytest


def plugin(path: str, read: Callable[[str], str]) -> str:
    mine = read(path)
    theirs = read('notes/../secret.txt')
    return mine + '|' + theirs


def run_plugin(path: str) -> str:
    """Run `plugin(path, read)` with a sandboxed reader and return its result.

    `read(p)` resolves `p` relative to the `notes` directory (in the current
    working directory) and returns the file's text. It returns "" when the
    resolved location (after collapsing `..` and following symlinks) lies
    outside `notes`, or when it cannot be read (missing, a directory,
    undecodable, permission error). Absolute paths outside `notes` also
    give "".
    """
    root = Path("notes").resolve()

    def read(p: str) -> str:
        try:
            target = (root / p).resolve()
            if not target.is_relative_to(root):
                return ""
            return target.read_text(encoding="utf-8")
        except (OSError, ValueError):
            return ""

    return plugin(path, read)


@pytest.fixture
def sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    notes.mkdir()
    (notes / "a.txt").write_text("A", encoding="utf-8")
    (notes / "sub").mkdir()
    (notes / "sub" / "b.txt").write_text("B", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("TOP", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_file_inside_notes(sandbox: Path) -> None:
    assert run_plugin("a.txt") == "A|"


def test_reads_nested_file(sandbox: Path) -> None:
    assert run_plugin("sub/b.txt") == "B|"


def test_dotdot_that_stays_inside_notes(sandbox: Path) -> None:
    assert run_plugin("sub/../a.txt") == "A|"


def test_plugin_cannot_read_secret_outside(sandbox: Path) -> None:
    result = run_plugin("a.txt")
    assert "TOP" not in result
    assert result.endswith("|")


def test_dotdot_escape_gives_empty(sandbox: Path) -> None:
    assert run_plugin("../secret.txt") == "|"


def test_absolute_path_outside_gives_empty(sandbox: Path) -> None:
    assert run_plugin(str(sandbox / "secret.txt")) == "|"


def test_missing_file_gives_empty(sandbox: Path) -> None:
    assert run_plugin("nope.txt") == "|"


def test_directory_gives_empty(sandbox: Path) -> None:
    assert run_plugin("sub") == "|"


def test_sibling_directory_with_notes_prefix_is_outside(sandbox: Path) -> None:
    evil = sandbox / "notes_evil"
    evil.mkdir()
    (evil / "x.txt").write_text("EVIL", encoding="utf-8")
    assert run_plugin("../notes_evil/x.txt") == "|"


def test_symlink_escape_gives_empty(sandbox: Path) -> None:
    link = sandbox / "notes" / "link.txt"
    try:
        link.symlink_to(sandbox / "secret.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert run_plugin("link.txt") == "|"
